"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import (InvalidRequest, Response, bad_request, not_found,
                                     require_positive_int)


class CustomerInsightsController:
    def __init__(self, service: OrderService, customers: CustomerService) -> None:
        self._service = service
        self._customers = customers

    def _lifetime_value(self, customer_id: str) -> tuple[int, int]:
        """Return (order_count, lifetime_value_cents), excluding cancelled orders."""
        orders = self._service.list_for_customer(customer_id)
        active = [o for o in orders if o.status != "cancelled"]
        return len(active), sum(self._service.summarize(o).total_cents for o in active)

    def handle_order_history(self, customer_id: str) -> Response:
        """Every order for a customer, newest first, with the same totals as the order summary."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        history: list[dict[str, Any]] = []
        for order in reversed(orders):  # creation order -> newest first
            summary = self._service.summarize(order)
            history.append({"order_id": order.order_id, "status": order.status,
                            "total_cents": summary.total_cents})
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders, excluding cancelled ones."""
        try:
            count, lifetime_value = self._lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": lifetime_value})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers with the highest lifetime value, skipping those with none."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, value = self._lifetime_value(customer.customer_id)
            if value > 0:
                ranked.append((value, customer))
        ranked.sort(key=lambda pair: (-pair[0], pair[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": c.customer_id, "name": c.name, "lifetime_value_cents": value}
            for value, c in ranked[:limit]]})

